final class CartPanel extends JPanel {         // container: owns state + wiring
    private final CartModel model = new CartModel();
    CartPanel() {
        JLabel count = new JLabel();               // passive children
        JButton add = new JButton("Add");
        add.addActionListener(e -> model.add());
        model.addListener(() -> count.setText(String.valueOf(model.count())));
        setLayout(new BoxLayout(this, BoxLayout.PAGE_AXIS));
        add(count); add(add);
    }
}
